class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)
        for i in range(n):
            # Check if index i-k exists and if nums[i] > nums[i-k]
            # Check if index i+k exists and if nums[i] > nums[i+k]
            # If neither index exists, it's still good.
            # So we need to check:
            # - If i-k exists, then nums[i] must be > nums[i-k]
            # - If i+k exists, then nums[i] must be > nums[i+k]
            # If both exist, both conditions must hold.
            # If only one exists, that condition must hold.
            # If neither exists, it's good.

            good = True
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    good = False
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    good = False
            if good:
                total += nums[i]
        return total
